SELECT id, ends_on, COUNT(discount_pct) OVER (PARTITION BY channel, promo_code ORDER BY starts_on ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_discount_pct, MAX(discount_pct) OVER (PARTITION BY channel, promo_code ORDER BY starts_on ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_discount_pct, MIN(discount_pct) OVER (PARTITION BY channel, promo_code ORDER BY starts_on ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_discount_pct, AVG(discount_pct) OVER (PARTITION BY channel, promo_code ORDER BY starts_on ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_discount_pct, SUM(discount_pct) OVER (PARTITION BY channel, promo_code ORDER BY starts_on ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_discount_pct FROM promotions
